        assert name in text, (f, name)
for name in ['preview', 'dev-db', 'development', 'burneto-shared-dev-database', 'ufekmuxkmodwydxmdbln', 'izuzqvgvgquqqimwuygw', '--skip-vault', '--include-all', 'reset', 'RLS', 'ダミーキー']:
